import { unzipSync, zipSync, gunzip as callbackGunzip, gzipSync, gunzipSync } from 'fflate'
import type { Zippable } from 'fflate'
import { FileSystem, TsMorphFileSystemWrapper } from './fs'
import type { Logger } from './logger'
import { path } from './path'

const ZIP_STATUS_FILE = 'status.json'

export const unzipAppPackage = async (
    fs: FileSystem,
    zipPath: string,
    targetPath: string,
    logger?: Logger,
    ignore?: (filename: string) => boolean
): Promise<{ files: string[] }> => {
    const zipArrBuf = new Uint8Array(fs.readFileSync(zipPath))
    const unzipResult = unzipSync(zipArrBuf)

    //remove unnecessary package inventory file if present
    if (unzipResult['package_inventory.csv']) {
        delete unzipResult['package_inventory.csv']
    }

    // check the status of download operation
    if (ZIP_STATUS_FILE in unzipResult) {
        const response = JSON.parse(Buffer.from(unzipResult[ZIP_STATUS_FILE]).toString('utf8'))
        if (response.status === 'error') {
            throw new Error(`Application download failed with error, ${response.message}`)
        }
        if (response.status === 'warning') {
            logger?.warn(`Application download completed with warning: ${response.message}`)
        }
        delete unzipResult[ZIP_STATUS_FILE]
    }

    const files: string[] = []
    for (const [filePath, data] of Object.entries(unzipResult)) {
        const filename = path.basename(filePath)

        if (ignore?.(filename)) {
            logger?.info(`Skipping file ${filename} due to excludeFilePatterns`)
            continue
        }

        const fullPath = path.join(targetPath, filePath)

        // Create directories if necessary
        FileSystem.ensureDirSync(fs, path.dirname(fullPath))

        // Write file content to the filesystem
        fs.writeFileSync(fullPath, data)

        files.push(fullPath)
    }

    return { files }
}

export const zipDirectory = async (fs: FileSystem, source: string, destination: string): Promise<string> => {
    // Using our own glob for browser compatibility
    const wrappedFs = new TsMorphFileSystemWrapper(fs)
    const files = wrappedFs.globSync(['**'], {
        cwd: source,
    })

    if (files.length === 0) {
        throw new Error(`No files found in ${source} directory to create zip.`)
    }

    const fileMap: Zippable = {}
    for (const file of files) {
        const fp = path.normalize(file)
        const data = new Uint8Array(fs.readFileSync(fp))
        const entryName = fp.replace(source, '')
        fileMap[entryName] = [data, { level: 6 }]
    }

    const zipped = zipSync(fileMap)
    fs.writeFileSync(destination, zipped)
    return destination
}

const gunzip = (data: Uint8Array) =>
    new Promise((resolve, reject) => {
        return callbackGunzip(data, (err, data) => {
            if (err) {
                reject(err)
            } else {
                resolve(data)
            }
        })
    }) as Promise<Uint8Array>

export const extractTarGz = async (
    tgzData: Uint8Array,
    targetPath: string,
    fs: FileSystem,
    options?: { prefix?: string }
): Promise<{ files: string[] }> => {
    // modern-tar is ESM-only and this package emits CommonJS, so it has to be
    // pulled in with a dynamic import. `module: Node16` leaves the import()
    // intact rather than downleveling it to require(), and the esbuild browser
    // bundles inline the module outright.
    const { unpackTar } = await import('modern-tar')

    const prefix = options?.prefix ?? ''
    // Use gunzipSync for browser compatibility - async gunzip spawns a Web Worker that fails in the IDE
    const entries = await unpackTar(gunzipSync(tgzData), {
        // Matching the prefix here rather than via `strip` is deliberate:
        // `strip` removes a fixed number of leading segments without checking
        // what they were, so entries from a sibling directory outside the
        // prefix would survive with a plausible-looking relative path.
        // `filter` sees the untransformed name, so the full prefix is matched
        // against the entry's real location.
        filter: (header) => header.name.startsWith(prefix),
    })

    const files: string[] = []

    for (const { header, data } of entries) {
        if (header.type !== 'file') {
            continue
        }

        // Tar entry names are attacker-controlled for any tarball resolved from
        // a registry, and modern-tar reports them verbatim. Normalizing collapses
        // '.', '..' and backslash separators; anything that still escapes the
        // target after that is rejected rather than written outside targetPath.
        const entryPath = path.normalize(header.name.slice(prefix.length))
        if (
            !entryPath ||
            entryPath === '.' ||
            entryPath === '..' ||
            entryPath.startsWith('../') ||
            path.isAbsolute(entryPath)
        ) {
            continue
        }
        if (path.basename(entryPath) === '.gitkeep') {
            continue
        }

        const fullPath = path.join(targetPath, entryPath)
        FileSystem.ensureDirSync(fs, path.dirname(fullPath))
        fs.writeFileSync(fullPath, data ?? new Uint8Array(0))
        files.push(fullPath)
    }

    return { files }
}

/**
 * Reads a single file entry out of a .tar.gz without extracting anything to disk.
 *
 * `entryName` must match the tar entry's name exactly, as reported by the archive
 * (npm tarballs prefix every path with `package/`).
 */
export const readTarGzEntry = async (tgzData: Uint8Array, entryName: string): Promise<Uint8Array | undefined> => {
    // Dynamic import for the same reason as extractTarGz: modern-tar is ESM-only.
    const { unpackTar } = await import('modern-tar')

    const entries = await unpackTar(gunzipSync(tgzData), {
        filter: (header) => header.name === entryName,
    })

    // An exact-name filter can still match a non-file entry (e.g. a directory of that name),
    // so pick the file entry rather than the first match. `data ?? empty` keeps an empty file
    // distinguishable from a missing one, which is the difference the caller acts on.
    const entry = entries.find(({ header }) => header.type === 'file')
    return entry === undefined ? undefined : (entry.data ?? new Uint8Array(0))
}

export { gzipSync, gunzip, gunzipSync, zipSync, unzipSync }
